let raw = $json.text;

if (typeof raw === 'string') {
  raw = JSON.parse(raw);
}

return [
  {
    json: {
      amount: raw.amount ?? null,

      // المستخدم يحددهم في شاشة المراجعة
      bucket: null,
      category: null,

      description: raw.description ?? null,

      paymentMethod:
        raw.paymentMethod ?? 'other',

      date: raw.date ?? null,

      confidence:
        raw.confidence ?? 0,

      sourceType: 'image'
    }
  }
];

const transcription = $input.first()?.json ?? {};

/*
 * استبدل اسم العقدة أدناه بالاسم الحقيقي للعقدة
 * التي تجهز requestId والعملة والتوقيت واللغة.
 */
let context = {};

try {
  context =
    $('Code in JavaScript').first()?.json ?? {};
} catch (_) {
  context = {};
}

function normalizeText(value) {
  if (typeof value !== 'string') {
    return '';
  }

  return value.trim();
}

function extractTranscript(data) {
  const candidates = [
    data.text,
    data.transcript,
    data.output,
    data.result?.text,
    data.result?.transcript,
    data.data?.text,
    data.data?.transcript,
    data.message?.content,
  ];

  for (const candidate of candidates) {
    const text = normalizeText(candidate);

    if (text) {
      return text;
    }
  }

  return '';
}

function normalizeCurrency(value) {
  const currency = normalizeText(value).toUpperCase();

  if (!currency) {
    return null;
  }

  const allowedCurrencies = new Set([
    'JOD',
    'USD',
    'EUR',
    'GBP',
    'SAR',
    'AED',
  ]);

  return allowedCurrencies.has(currency)
    ? currency
    : null;
}

function normalizeTimezone(value) {
  const timezone = normalizeText(value);

  return timezone || 'Asia/Amman';
}

function normalizeLanguage(value) {
  const language = normalizeText(value).toLowerCase();

  if (!language) {
    return 'ar';
  }

  return language;
}

function getDateInTimezone(timezone) {
  try {
    return new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).format(new Date());
  } catch (_) {
    return new Date().toISOString().slice(0, 10);
  }
}

function getTranscriptionDuration(data) {
  const candidates = [
    data.usage?.seconds,
    data.duration,
    data.durationSeconds,
    data.metadata?.durationSeconds,
  ];

  for (const candidate of candidates) {
    const duration = Number(candidate);

    if (
      Number.isFinite(duration) &&
      duration >= 0
    ) {
      return duration;
    }
  }

  return null;
}

const transcript = extractTranscript(transcription);

/*
 * بما أن العقدة متصلة مباشرة بالـAI،
 * لا نرسل طلب AI إذا لم يوجد نص واضح.
 */
if (!transcript) {
  throw new Error(
    'VOICE_TRANSCRIPT_EMPTY: تعذر استخراج نص واضح من التسجيل الصوتي.'
  );
}

const previousContext =
  context.transactionContext ??
  context.receiptContext ??
  {};

const userCurrency =
  normalizeCurrency(
    context.userCurrency ??
    previousContext.userCurrency ??
    context.currency
  ) ?? 'JOD';

const userTimezone =
  normalizeTimezone(
    context.userTimezone ??
    previousContext.userTimezone ??
    context.timezone
  );

const language =
  normalizeLanguage(
    context.language ??
    previousContext.language
  );

const currentDate =
  getDateInTimezone(userTimezone);

return [
  {
    json: {
      valid: true,

      requestId:
        context.requestId ??
        previousContext.requestId ??
        null,

      type: 'voice',
      inputType: 'voice',

      /*
       * النص الذي سترسله عقدة Extract Voice إلى الـAI.
       */
      transcript,
      commandText: transcript,

      /*
       * السياق المسموح بإرساله إلى الـAI.
       */
      aiContext: {
        userCurrency,
        currentDate,
        userTimezone,
        language,
      },

      /*
       * سياق داخلي لباقي عقد workflow.
       * لا تضع userId داخل رسالة الـAI.
       */
      transactionContext: {
        ...previousContext,
        type: 'voice',
        inputType: 'voice',
        transcript,
        commandText: transcript,
        userCurrency,
        currentDate,
        userTimezone,
        language,
      },

      metadata: {
        ...(context.metadata ?? {}),
        stage: 'voice_transcription',
        transcriptionDurationSeconds:
          getTranscriptionDuration(
            transcription
          ),
        transcribedAt:
          new Date().toISOString(),
      },
    },
  },
];

