// -----------------------------------------------
// Alpha— Receipt: Build safe AI-processing error
// -----------------------------------------------

const sourceInput =
  $('02 — Prepare Transaction Context').first().json ?? {};

const context =
  sourceInput.receiptContext ?? {};

const rawError =
  $json.error ??
  $json;

const rawMessage =
  typeof rawError === 'string'
    ? rawError
    : rawError?.message ??
      rawError?.description ??
      rawError?.cause?.message ??
      'Unknown receipt processing error';

const normalizedMessage =
  String(rawMessage).toLowerCase();

let errorCode =
  'RECEIPT_PROCESSING_FAILED';

let retryable = true;

let stage =
  'receipt_extraction';

if (
  normalizedMessage.includes('rate limit') ||
  normalizedMessage.includes('too many requests') ||
  normalizedMessage.includes('429')
) {
  errorCode = 'RECEIPT_AI_RATE_LIMITED';
  retryable = true;
}

if (
  normalizedMessage.includes('timeout') ||
  normalizedMessage.includes('timed out') ||
  normalizedMessage.includes('etimedout')
) {
  errorCode = 'RECEIPT_AI_TIMEOUT';
  retryable = true;
}

if (
  normalizedMessage.includes('parse') ||
  normalizedMessage.includes('parser') ||
  normalizedMessage.includes('json') ||
  normalizedMessage.includes('schema') ||
  normalizedMessage.includes('structured output')
) {
  errorCode = 'RECEIPT_OUTPUT_PARSER_FAILED';
  retryable = true;
  stage = 'output_parsing';
}

if (
  normalizedMessage.includes('image') &&
  (
    normalizedMessage.includes('invalid') ||
    normalizedMessage.includes('unsupported') ||
    normalizedMessage.includes('decode')
  )
) {
  errorCode = 'RECEIPT_IMAGE_PROCESSING_FAILED';
  retryable = false;
  stage = 'image_processing';
}

if (
  normalizedMessage.includes('authentication') ||
  normalizedMessage.includes('unauthorized') ||
  normalizedMessage.includes('invalid api key') ||
  normalizedMessage.includes('401')
) {
  errorCode = 'RECEIPT_AI_CONFIGURATION_ERROR';
  retryable = false;
  stage = 'ai_configuration';
}

const language =
  context.language === 'en'
    ? 'en'
    : 'ar';

const userMessage =
  language === 'en'
    ? retryable
      ? 'The receipt could not be read right now. Please try again with a clearer image.'
      : 'The receipt image could not be processed. Please upload a supported, clear image.'
    : retryable
      ? 'تعذر قراءة الإيصال الآن. يرجى إعادة المحاولة بصورة أوضح.'
      : 'تعذر معالجة صورة الإيصال. يرجى رفع صورة واضحة ومن نوع مدعوم.';

const processingStartedAt =
  context.timing?.processingStartedAt ??
  sourceInput.metadata?.processingStartedAt ??
  null;

const processingTimeMs =
  typeof processingStartedAt === 'number'
    ? Math.max(
        0,
        Date.now() - processingStartedAt,
      )
    : null;

return {
  json: {
    success: false,

    requestId:
      sourceInput.requestId ?? null,

    userId:
      sourceInput.userId ?? null,

    type: 'receipt',

    timestamp: new Date().toISOString(),

    error: {
      code: errorCode,
      message: userMessage,
      retryable,
    },

    metadata: {
      workflowName: 'Alpha— Receipt',
      version: '1.0.0',
      language,
      stage,
      aiUsed: true,
      processingTimeMs,
      requiresUserConfirmation: false,
    },
  },
};

const allowedTransactionTypes = new Set([
  'expense',
  'income',
]);

const allowedCategories = new Set([
  'housing',
  'utilities',
  'groceries',
  'transportation',
  'healthcare',
  'education',
  'insurance',
  'debt_minimum_payment',
  'restaurants',
  'coffee',
  'shopping',
  'subscriptions',
  'entertainment',
  'travel',
  'gifts',
  'electronics',
  'fashion',
  'personal_care',
  'salary',
  'freelance',
  'investment_income',
  'gifts_income',
  'other',
]);

const allowedCurrencies = new Set([
  'JOD',
  'USD',
  'EUR',
  'GBP',
  'SAR',
  'AED',
]);

function parsePossibleJson(value) {
  if (value === null || value === undefined) {
    return null;
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string') {
    return null;
  }

  const trimmed = value.trim();

  if (!trimmed) {
    return null;
  }

  try {
    return JSON.parse(trimmed);
  } catch (_) {
    return null;
  }
}

function extractParserResult(itemJson) {
  const candidates = [
    itemJson,
    itemJson.output,
    itemJson.result,
    itemJson.data,
    itemJson.response,
    itemJson.content,
    itemJson.text,
    itemJson.message?.content,
  ];

  for (const candidate of candidates) {
    const parsed = parsePossibleJson(candidate);

    if (
      parsed &&
      typeof parsed === 'object' &&
      Array.isArray(parsed.transactions)
    ) {
      return parsed;
    }
  }

  return null;
}

function normalizeString(value) {
  if (typeof value !== 'string') {
    return null;
  }

  const normalized = value.trim();

  return normalized.length > 0
    ? normalized
    : null;
}

function normalizeAmount(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const amount = Number(value);

  if (!Number.isFinite(amount) || amount <= 0) {
    return null;
  }

  return Math.round(amount * 100) / 100;
}

function normalizeConfidence(value) {
  const numeric = Number(value);

  if (!Number.isFinite(numeric)) {
    return 0;
  }

  return Math.max(
    0,
    Math.min(100, Math.round(numeric)),
  );
}

function normalizeDate(value) {
  const raw = normalizeString(value);

  if (!raw) {
    return null;
  }

  const exactDatePattern = /^\d{4}-\d{2}-\d{2}$/;

  if (exactDatePattern.test(raw)) {
    const parsed = new Date(`${raw}T00:00:00Z`);

    if (!Number.isNaN(parsed.getTime())) {
      return raw;
    }
  }

  const parsed = new Date(raw);

  if (Number.isNaN(parsed.getTime())) {
    return null;
  }

  return [
    parsed.getFullYear(),
    String(parsed.getMonth() + 1).padStart(2, '0'),
    String(parsed.getDate()).padStart(2, '0'),
  ].join('-');
}

function normalizeUncertainFields(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return [
    ...new Set(
      value
        .filter((item) => typeof item === 'string')
        .map((item) => item.trim())
        .filter(Boolean),
    ),
  ];
}

function addUncertainField(fields, fieldName) {
  if (!fields.includes(fieldName)) {
    fields.push(fieldName);
  }
}

const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error('VOICE_PROCESSING_FAILED: No input received');
}

const parsedResult = extractParserResult(
  inputItems[0].json,
);

if (
  !parsedResult ||
  !Array.isArray(parsedResult.transactions) ||
  parsedResult.transactions.length === 0
) {
  throw new Error(
    'VOICE_PROCESSING_FAILED: No transactions extracted',
  );
}

const transactions = parsedResult.transactions.map(
  (rawTransaction, index) => {
    if (
      !rawTransaction ||
      typeof rawTransaction !== 'object' ||
      Array.isArray(rawTransaction)
    ) {
      throw new Error(
        `VOICE_PROCESSING_FAILED: Invalid transaction at index ${index}`,
      );
    }

    const uncertainFields = normalizeUncertainFields(
      rawTransaction.uncertainFields,
    );

    let transactionType = normalizeString(
      rawTransaction.transactionType,
    )?.toLowerCase();

    if (
      !transactionType ||
      !allowedTransactionTypes.has(transactionType)
    ) {
      transactionType = null;
      addUncertainField(
        uncertainFields,
        'transactionType',
      );
    }

    const amount = normalizeAmount(
      rawTransaction.amount,
    );

    if (amount === null) {
      addUncertainField(
        uncertainFields,
        'amount',
      );
    }

    let currency = normalizeString(
      rawTransaction.currency,
    )?.toUpperCase();

    if (
      currency &&
      !allowedCurrencies.has(currency)
    ) {
      currency = null;
      addUncertainField(
        uncertainFields,
        'currency',
      );
    }

    if (!currency) {
      currency = null;
      addUncertainField(
        uncertainFields,
        'currency',
      );
    }

    let category = normalizeString(
      rawTransaction.category,
    )?.toLowerCase();

    if (
      !category ||
      !allowedCategories.has(category)
    ) {
      category = null;
      addUncertainField(
        uncertainFields,
        'category',
      );
    }

    const description = normalizeString(
      rawTransaction.description,
    );

    if (!description) {
      addUncertainField(
        uncertainFields,
        'description',
      );
    }

    const merchant = normalizeString(
      rawTransaction.merchant,
    );

    if (!merchant) {
      addUncertainField(
        uncertainFields,
        'merchant',
      );
    }

    const date = normalizeDate(
      rawTransaction.date,
    );

    if (!date) {
      addUncertainField(
        uncertainFields,
        'date',
      );
    }

    const confidence = normalizeConfidence(
      rawTransaction.confidence,
    );

    return {
      transactionType,
      amount,
      currency,
      category,
      description,
      merchant,
      date,
      confidence,
      uncertainFields,
    };
  },
);

return [
  {
    json: {
      success: true,
      message: 'Voice parsed successfully',
      data: {
        sourceType: 'voice',
        transactions,
      },
      meta: {
        transactionCount: transactions.length,
        requiresReview: transactions.some(
          (transaction) =>
            transaction.confidence < 70 ||
            transaction.uncertainFields.length > 0,
        ),
      },
    },
  },
];

return [{
  json: {
    type: $json.body?.type || 'image',
    inputType: $json.body?.type || 'image',

    receiptContext: {
      language: 'auto',
      options: {
        extractItems: true,
        suggestCategory: true
      }
    }
  },
  binary: {
    receiptImage: $binary.file
  }
}];
